import{_ as d}from"./chunks/placeholder-user-region-config-admin.DTnJja0f.js";import{_ as r,o,c as s,a2 as n}from"./chunks/framework.CRFziyHp.js";const p=JSON.parse('{"title":"用户规则（区域用户配置）","description":"用户规则（区域用户配置）：灵萌 后台配置官方文档，面向站点管理员与运营人员，含配置步骤与注意事项。","frontmatter":{},"headers":[],"relativePath":"config/user-rules.md","filePath":"config/user-rules.md","lastUpdated":1785018026000}'),a={name:"config/user-rules.md"};function g(e,t,h,l,i,b){return o(),s("div",null,[...t[0]||(t[0]=[n('<h1 id="用户规则-区域用户配置" tabindex="-1">用户规则（区域用户配置） <a class="header-anchor" href="#用户规则-区域用户配置" aria-label="Permalink to &quot;用户规则（区域用户配置）&quot;">​</a></h1><p>路径：<strong>区域管理 → 用户配置</strong></p><p>控制用户<strong>如何注册、登录、填写资料、签到、认证</strong>，可按区域分别设置。本文逐项说明<strong>每个开关/字段在 C 端（小程序 / H5）的实际表现</strong>，便于运营验收。</p><p><img src="'+d+'" alt="区域用户配置"></p><hr><h2 id="操作入口与配置继承" tabindex="-1">操作入口与配置继承 <a class="header-anchor" href="#操作入口与配置继承" aria-label="Permalink to &quot;操作入口与配置继承&quot;">​</a></h2><h3 id="后台怎么配" tabindex="-1">后台怎么配 <a class="header-anchor" href="#后台怎么配" aria-label="Permalink to &quot;后台怎么配&quot;">​</a></h3><ol><li>打开 <strong>区域管理 → 用户配置</strong></li><li>列表中点某条配置进入编辑弹窗（需有编辑权限）</li><li>新建时先选 <strong>目标区域</strong>： <ul><li>选 <strong>平台默认（区域编号 0）</strong>：全站兜底规则</li><li>选具体区域：仅对该区域用户生效</li></ul></li><li>改完点 <strong>保存</strong></li></ol><h3 id="生效优先级-运营需理解" tabindex="-1">生效优先级（运营需理解） <a class="header-anchor" href="#生效优先级-运营需理解" aria-label="Permalink to &quot;生效优先级（运营需理解）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>用户所属区域</th><th>实际读取哪份配置</th></tr></thead><tbody><tr><td>某校区有专属配置</td><td>用该校区配置</td></tr><tr><td>某校区无专属配置</td><td>回退 <strong>平台默认（0）</strong></td></tr><tr><td>平台默认也没有</td><td>使用系统内置默认值（偏宽松：可注册、可登录等）</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">「启用」不是「回退平台默认」</p><p>某区域若<strong>已新建专属配置</strong>但把 <strong>启用</strong> 关掉，系统仍读取这条配置，且会<strong>直接拦截</strong>注册、登录、改资料，<strong>不会</strong>自动改用平台默认。</p><p>若希望某区域跟全站一致：<strong>不要</strong>为其单独建配置，或删除该区域专属行。</p></div><h3 id="与区域列表的关系" tabindex="-1">与区域列表的关系 <a class="header-anchor" href="#与区域列表的关系" aria-label="Permalink to &quot;与区域列表的关系&quot;">​</a></h3><ul><li><strong>区域列表</strong>（<a href="/config/region">区域管理</a>）：定义有哪些校区/社区、是否对用户可见、距离限制、私信开关等</li><li><strong>用户配置</strong>（本文）：定义用户在该区域的行为规则</li></ul><p>两者独立配置，需配合使用。</p><hr><h2 id="一、注册与登录" tabindex="-1">一、注册与登录 <a class="header-anchor" href="#一、注册与登录" aria-label="Permalink to &quot;一、注册与登录&quot;">​</a></h2><table tabindex="0"><thead><tr><th>后台字段</th><th>开启 / 关闭</th><th>C 端表现</th><th>验收要点</th></tr></thead><tbody><tr><td><strong>启用</strong></td><td>关</td><td>该区域用户：<strong>无法注册</strong>、<strong>无法微信/密码登录</strong>、<strong>无法修改资料</strong>；提示「当前区域暂未开放…」</td><td>用该区域测试账号分别试注册、登录、改昵称</td></tr><tr><td><strong>启用</strong></td><td>开</td><td>下方子开关按配置生效</td><td>—</td></tr><tr><td><strong>允许账号注册</strong></td><td>关</td><td>注册页提交失败，提示「当前区域暂未开放注册」；微信首次授权若需自动注册也会受限于区域策略</td><td>新用户走一遍注册</td></tr><tr><td><strong>允许密码登录</strong></td><td>关</td><td>用户名+密码登录失败，提示「当前区域暂未开放密码登录」；微信登录不受影响（若微信登录仍开启）</td><td>密码登录与微信登录各测一次</td></tr><tr><td><strong>允许微信小程序登录</strong></td><td>关</td><td>小程序内微信授权登录失败，提示「当前区域暂未开放微信小程序登录」</td><td>在小程序登录页测试</td></tr><tr><td><strong>允许微信公众号登录</strong></td><td>关</td><td>H5 / 公众号内微信登录失败，提示「当前区域暂未开放微信公众号登录」</td><td>在 H5 登录页测试</td></tr><tr><td><strong>注册强制验证码</strong></td><td>开</td><td>注册时必须填写图形验证码，否则无法提交</td><td>注册页应出现验证码</td></tr><tr><td><strong>注册强制验证码</strong></td><td>关</td><td>注册可不填验证码（仍受其他校验约束）</td><td>—</td></tr><tr><td><strong>登录强制验证码</strong></td><td>开</td><td>密码登录时必须填验证码</td><td>登录页出现验证码</td></tr><tr><td><strong>登录强制验证码</strong></td><td>关</td><td>密码登录无需验证码</td><td>—</td></tr></tbody></table><p><strong>常见组合示例</strong></p><table tabindex="0"><thead><tr><th>运营目标</th><th>建议配置</th></tr></thead><tbody><tr><td>只要微信、不要账号密码</td><td>关「允许密码登录」+ 开对应微信登录 + 关「允许账号注册」（若也不希望新用户用用户名注册）</td></tr><tr><td>校内只允许老用户登录</td><td>关「允许账号注册」，保留登录方式</td></tr><tr><td>防机器注册</td><td>开「注册强制验证码」</td></tr></tbody></table><p><strong>前置依赖</strong>：微信登录开关生效前，须先在 <a href="/config/system-settings">系统配置 → 微信小程序 / 微信公众号</a> 填好 AppID 等，并完成 <a href="/features/wechat">微信功能开启</a>。</p><hr><h2 id="二、长度限制" tabindex="-1">二、长度限制 <a class="header-anchor" href="#二、长度限制" aria-label="Permalink to &quot;二、长度限制&quot;">​</a></h2><table tabindex="0"><thead><tr><th>后台字段</th><th>取值</th><th>C 端表现</th></tr></thead><tbody><tr><td>用户名最小 / 最大</td><td>如 3～32</td><td>注册时用户名过短/过长会提示，无法提交</td></tr><tr><td>密码最小 / 最大</td><td>如 6～64</td><td>注册或改密码时不符合长度会提示</td></tr><tr><td>昵称最小 / 最大</td><td>如 1～50</td><td>注册、改昵称、引导页填昵称时校验</td></tr><tr><td>简介最大长度</td><td>如 500</td><td>个人资料改简介时超出上限会提示</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>长度为 <strong>0 或未填</strong> 时按系统默认处理；改小最大值可能影响已有用户再次保存资料。</p></div><hr><h2 id="三、注册策略" tabindex="-1">三、注册策略 <a class="header-anchor" href="#三、注册策略" aria-label="Permalink to &quot;三、注册策略&quot;">​</a></h2><table tabindex="0"><thead><tr><th>后台字段</th><th>开启 / 取值</th><th>C 端表现</th><th>验收要点</th></tr></thead><tbody><tr><td><strong>注册时必须选择区域</strong></td><td>开</td><td>账号密码注册时必须选所属区域，否则提示「请选择所属区域」</td><td>多区域模式下注册页应出现区域选择</td></tr><tr><td><strong>允许绑定推广人</strong></td><td>开</td><td>注册时可携带推广人 ID，成功后尝试绑定推广关系（绑定失败不影响注册本身）</td><td>带推广参数注册，后台查推广关系</td></tr><tr><td><strong>允许绑定推广人</strong></td><td>关</td><td>注册时忽略推广人绑定</td><td>—</td></tr><tr><td><strong>注册时使用更严格默认隐私</strong></td><td>开</td><td>新用户默认：<strong>不可被搜索</strong>、<strong>点赞列表不可见</strong>、<strong>关注列表不可见</strong></td><td>新注册用户查隐私相关开关默认值</td></tr><tr><td><strong>注册时使用更严格默认隐私</strong></td><td>关</td><td>新用户使用系统默认隐私（相对开放）</td><td>—</td></tr><tr><td><strong>新用户信息模式</strong></td><td>跟随全站</td><td>使用 <a href="/config/system-settings#tab-10功能与上传">系统配置 → 功能与上传</a> 里的「新用户信息模式」</td><td>—</td></tr><tr><td><strong>新用户信息模式</strong></td><td>空白</td><td>注册后昵称/头像为空或默认占位，用户需自行填写</td><td>新用户资料页应较「空」</td></tr><tr><td><strong>新用户信息模式</strong></td><td>随机头像昵称</td><td>注册后自动分配随机昵称与头像</td><td>新用户应有非空昵称头像</td></tr><tr><td><strong>新用户信息模式</strong></td><td>头像库</td><td>从头像库随机分配头像（昵称策略同随机模式）</td><td>头像来自预设库</td></tr></tbody></table><hr><h2 id="四、资料与审核-基础" tabindex="-1">四、资料与审核（基础） <a class="header-anchor" href="#四、资料与审核-基础" aria-label="Permalink to &quot;四、资料与审核（基础）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>后台字段</th><th>开启 / 关闭</th><th>C 端表现</th></tr></thead><tbody><tr><td><strong>开启资料审核</strong></td><td>关</td><td>用户改昵称/头像/简介/背景图（在允许修改的前提下）<strong>立即生效</strong>，无需等待审核</td></tr><tr><td><strong>开启资料审核</strong></td><td>开</td><td>命中「需审核字段」的修改进入待审；详见下文「资料审核详情」</td></tr><tr><td><strong>允许修改昵称</strong></td><td>关</td><td>个人资料页改昵称失败，「当前区域不允许修改昵称」</td></tr><tr><td><strong>允许修改头像</strong></td><td>关</td><td>无法更换头像</td></tr><tr><td><strong>允许修改简介</strong></td><td>关</td><td>无法改简介</td></tr><tr><td><strong>允许修改背景图</strong></td><td>关</td><td>无法改个人主页背景</td></tr><tr><td><strong>昵称修改冷却（天）</strong></td><td>0</td><td>不限次数</td></tr><tr><td><strong>昵称修改冷却（天）</strong></td><td>N（如 7）</td><td>N 天内再次改昵称会提示需等待，无法提交</td></tr><tr><td><strong>资料完善阈值</strong></td><td>0～100</td><td>用于资料完善度进度、引导页是否算「已完善」；默认 80。用户资料页可见完善度百分比</td></tr><tr><td><strong>强制新用户引导</strong></td><td>开</td><td>资料未完善时：发笔记、评论等关键操作会 <strong>Toast「请先完善个人资料」并跳转引导页</strong>；选区域后若资料不达标也会引导</td></tr><tr><td><strong>强制新用户引导</strong></td><td>关</td><td>不强制跳转引导页；部分场景改为弹出资料授权弹层（头像/昵称/性别）</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">强制引导与区域列表</p><p>区域 <strong>用户配置</strong> 里的「强制新用户引导」为主配置。若区域在 <strong>区域列表</strong> 里也开了同类开关，<strong>任一开启即视为开启</strong>（兼容旧数据）。</p></div><p><strong>完善资料判定（C 端）</strong>：资料完善度 ≥ 阈值，或同时有有效头像 + 有效昵称（非「游客」「微信用户」等占位）。</p><hr><h2 id="五、用户标签" tabindex="-1">五、用户标签 <a class="header-anchor" href="#五、用户标签" aria-label="Permalink to &quot;五、用户标签&quot;">​</a></h2><table tabindex="0"><thead><tr><th>后台字段</th><th>开启 / 关闭</th><th>C 端表现</th></tr></thead><tbody><tr><td><strong>开放用户标签</strong></td><td>关</td><td>个人资料不展示标签能力；选标签、保存标签接口拒绝</td></tr><tr><td><strong>开放用户标签</strong></td><td>开</td><td>资料页可查看/选择标签（若允许编辑）</td></tr><tr><td><strong>允许用户修改标签</strong></td><td>关</td><td>标签只读，无法增删</td></tr><tr><td><strong>允许用户修改标签</strong></td><td>开</td><td>用户可自行调整标签</td></tr><tr><td><strong>最少选择数</strong></td><td>0</td><td>不强制选标签</td></tr><tr><td><strong>最少选择数</strong></td><td>N</td><td>保存资料时标签少于 N 个会提示</td></tr><tr><td><strong>最多选择数</strong></td><td>N</td><td>最多选 N 个，超出无法添加</td></tr><tr><td><strong>标签计入资料完善度</strong></td><td>开</td><td>选够标签会提高资料完善度百分比</td></tr><tr><td><strong>标签计入资料完善度</strong></td><td>关</td><td>标签不影响完善度计算</td></tr></tbody></table><hr><h2 id="六、资料审核详情" tabindex="-1">六、资料审核详情 <a class="header-anchor" href="#六、资料审核详情" aria-label="Permalink to &quot;六、资料审核详情&quot;">​</a></h2><p>在 <strong>开启资料审核</strong> 的前提下生效。</p><table tabindex="0"><thead><tr><th>后台字段</th><th>取值</th><th>C 端表现</th></tr></thead><tbody><tr><td><strong>需审核的资料字段</strong></td><td>不选</td><td>默认审核：昵称、头像、简介、背景图</td></tr><tr><td><strong>需审核的资料字段</strong></td><td>勾选部分</td><td>仅勾选字段修改时才进审核</td></tr><tr><td><strong>资料审核模式</strong></td><td>人工审核</td><td>提交后待管理员/审核中心通过才对外展示新版本</td></tr><tr><td><strong>资料审核模式</strong></td><td>自动通过</td><td>提交后系统自动通过（仍走审核流程记录）</td></tr><tr><td><strong>资料审核模式</strong></td><td>AI 审核</td><td>由 AI 审核引擎判定（须已开启 <a href="/features/ai">AI 中台</a>）</td></tr><tr><td><strong>审核中对外展示 → 继续显示旧资料</strong></td><td>—</td><td>他人和自己看到的仍是修改前的昵称/头像等，直到审核通过</td></tr><tr><td><strong>审核中对外展示 → 隐藏待审字段</strong></td><td>—</td><td>待审中的字段在资料页显示为空</td></tr><tr><td><strong>审核中对外展示 → 显示占位内容</strong></td><td>—</td><td>昵称/简介等显示「审核中」，头像/背景可能为空</td></tr></tbody></table><p>用户本人资料页会标记 <strong>有待审资料</strong>；审核结果会通过站内通知等方式告知（以实际通知配置为准）。</p><hr><h2 id="七、认证与门禁" tabindex="-1">七、认证与门禁 <a class="header-anchor" href="#七、认证与门禁" aria-label="Permalink to &quot;七、认证与门禁&quot;">​</a></h2><table tabindex="0"><thead><tr><th>后台字段</th><th>开启 / 关闭</th><th>C 端表现</th></tr></thead><tbody><tr><td><strong>开放学生认证</strong></td><td>关</td><td>学生认证入口不可用；提交认证提示「当前区域暂未开放学生认证」</td></tr><tr><td><strong>开放学生认证</strong></td><td>开</td><td>用户可进入学生认证流程</td></tr><tr><td><strong>要求学生认证通过</strong></td><td>关</td><td>未认证用户正常使用发笔记、评论、私信、签到、发现流等（各业务自身规则仍适用）</td></tr><tr><td><strong>要求学生认证通过</strong></td><td>开</td><td><strong>未通过学生认证</strong>（auth_status ≠ 已通过）的用户会被拦截，提示「请先完成学生认证后再使用该功能」。典型受限操作：<strong>发笔记、评论、发消息、签到、浏览发现流</strong>等</td></tr><tr><td><strong>禁用手工提交学生认证</strong></td><td>开</td><td>用户无法手动填写材料提交；仅适合纯官方渠道场景</td></tr><tr><td><strong>禁用手工提交学生认证</strong></td><td>关</td><td>可人工填写学校、学号、证件等提交审核</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>「开放学生认证」管<strong>有没有入口</strong>；「要求学生认证通过」管<strong>未认证能否用核心功能</strong>。两者需配合：要强制门禁时，两项通常都开。</p></div><p>管理员账号不受学生认证门禁限制。</p><hr><h2 id="八、账号安全与签到" tabindex="-1">八、账号安全与签到 <a class="header-anchor" href="#八、账号安全与签到" aria-label="Permalink to &quot;八、账号安全与签到&quot;">​</a></h2><table tabindex="0"><thead><tr><th>后台字段</th><th>开启 / 关闭 / 取值</th><th>C 端表现</th></tr></thead><tbody><tr><td><strong>允许账号注销</strong></td><td>关</td><td>设置里无注销入口或提交失败</td></tr><tr><td><strong>允许账号注销</strong></td><td>开</td><td>用户可发起注销流程</td></tr><tr><td><strong>允许绑定手机</strong></td><td>关</td><td>无法绑定/换绑手机号</td></tr><tr><td><strong>允许绑定手机</strong></td><td>开</td><td>账号安全页可绑手机</td></tr><tr><td><strong>允许绑定邮箱</strong></td><td>关</td><td>无法绑定邮箱</td></tr><tr><td><strong>允许绑定邮箱</strong></td><td>开</td><td>可绑邮箱</td></tr><tr><td><strong>开启签到</strong></td><td>关</td><td>签到页不可用；签到接口拒绝</td></tr><tr><td><strong>开启签到</strong></td><td>开</td><td>每日签到、签到概览正常（仍受学生认证门禁约束，若开启）</td></tr><tr><td><strong>注销确认冷却（小时）</strong></td><td>N</td><td>发起注销后需等待 N 小时才真正执行（防误操作）</td></tr><tr><td><strong>补签回溯天数</strong></td><td>N（默认 7）</td><td>用户可对过去 N 天内漏签日期发起补签（若产品页有补签入口）</td></tr></tbody></table><hr><h2 id="九、签到提醒-时间定义" tabindex="-1">九、签到提醒（时间定义） <a class="header-anchor" href="#九、签到提醒-时间定义" aria-label="Permalink to &quot;九、签到提醒（时间定义）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>后台字段</th><th>开启 / 取值</th><th>C 端表现</th></tr></thead><tbody><tr><td><strong>开启签到订阅提醒</strong></td><td>关</td><td>不向用户推送签到提醒类订阅消息</td></tr><tr><td><strong>开启签到订阅提醒</strong></td><td>开</td><td>按下方时刻，对「昨日已签、今日未签」且已授权订阅的用户推送小程序订阅消息</td></tr><tr><td><strong>签到提醒推送时刻（时）</strong></td><td>0～23</td><td>东八区每天该整点触发，如 <strong>10</strong> = 10:00</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">INFO</p><p>用户须在前端授权过对应 <strong>订阅消息</strong> 模板，否则无法收到提醒。</p></div><hr><h2 id="十、登录安全" tabindex="-1">十、登录安全 <a class="header-anchor" href="#十、登录安全" aria-label="Permalink to &quot;十、登录安全&quot;">​</a></h2><table tabindex="0"><thead><tr><th>后台字段</th><th>取值</th><th>C 端表现</th></tr></thead><tbody><tr><td><strong>登录失败锁定阈值</strong></td><td>0</td><td><strong>沿用全站</strong>登录失败锁定策略（见系统级安全配置）</td></tr><tr><td><strong>登录失败锁定阈值</strong></td><td>N</td><td>该区域用户密码登录连续失败 N 次后锁定</td></tr><tr><td><strong>登录锁定时长（分钟）</strong></td><td>0</td><td>沿用全站锁定时长</td></tr><tr><td><strong>登录锁定时长（分钟）</strong></td><td>M</td><td>锁定 M 分钟后自动解除</td></tr></tbody></table><p>仅影响 <strong>密码登录</strong> 的失败计数；微信登录不走同一套密码失败锁定。</p><hr><h2 id="十一、文案与备注" tabindex="-1">十一、文案与备注 <a class="header-anchor" href="#十一、文案与备注" aria-label="Permalink to &quot;十一、文案与备注&quot;">​</a></h2><table tabindex="0"><thead><tr><th>后台字段</th><th>C 端表现</th></tr></thead><tbody><tr><td><strong>注册页说明</strong></td><td>展示在注册表单上方（富文本/纯文本以页面渲染为准）</td></tr><tr><td><strong>登录页说明</strong></td><td>展示在登录表单上方</td></tr><tr><td><strong>区域入口说明</strong></td><td>展示在区域选择/入口相关提示位</td></tr><tr><td><strong>运营备注</strong></td><td><strong>仅后台可见</strong>，C 端不展示</td></tr></tbody></table><hr><h2 id="配置示例与验收清单" tabindex="-1">配置示例与验收清单 <a class="header-anchor" href="#配置示例与验收清单" aria-label="Permalink to &quot;配置示例与验收清单&quot;">​</a></h2><h3 id="示例-a-新校区-—-必须学生认证才能玩" tabindex="-1">示例 A：新校区 — 必须学生认证才能玩 <a class="header-anchor" href="#示例-a-新校区-—-必须学生认证才能玩" aria-label="Permalink to &quot;示例 A：新校区 — 必须学生认证才能玩&quot;">​</a></h3><ol><li><a href="/config/region">区域列表</a> 新建「XX 大学」并 <strong>启用</strong></li><li><strong>用户配置</strong> 为该区域新建配置，<strong>启用</strong> 打开</li><li>开「开放学生认证」+ 开「要求学生认证通过」</li><li>按需开「强制新用户引导」</li></ol><p><strong>验收</strong></p><ul><li>[ ] 未认证用户发笔记 / 评论 / 私信 / 签到应被拦截并提示认证</li><li>[ ] 认证通过后上述功能恢复</li><li>[ ] 资料未完善时引导页逻辑符合预期</li></ul><h3 id="示例-b-全站仅微信登录" tabindex="-1">示例 B：全站仅微信登录 <a class="header-anchor" href="#示例-b-全站仅微信登录" aria-label="Permalink to &quot;示例 B：全站仅微信登录&quot;">​</a></h3><ol><li>编辑 <strong>平台默认（0）</strong></li><li>关「允许密码登录」、关「允许账号注册」（可选）</li><li>开「允许微信小程序登录」</li></ol><p><strong>验收</strong></p><ul><li>[ ] 小程序可微信登录</li><li>[ ] 密码登录明确失败提示</li><li>[ ] 系统配置里微信 AppID 已生效</li></ul><h3 id="示例-c-资料改完需人工审" tabindex="-1">示例 C：资料改完需人工审 <a class="header-anchor" href="#示例-c-资料改完需人工审" aria-label="Permalink to &quot;示例 C：资料改完需人工审&quot;">​</a></h3><ol><li>开「开启资料审核」</li><li>审核模式选 <strong>人工审核</strong></li><li>「审核中对外展示」选 <strong>继续显示旧资料</strong></li></ol><p><strong>验收</strong></p><ul><li>[ ] 用户改昵称后对外仍显示旧昵称</li><li>[ ] 本人能看到待审状态</li><li>[ ] 后台审核通过后新昵称生效</li></ul><hr><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="/config/region">区域管理</a> — 区域列表、距离限制、区域私信、提现等区域级开关</li><li><a href="/config/system-settings">系统配置 → 区域配置 / 功能与上传</a> — 全站区域模式、距离限制、默认新用户信息模式</li><li><a href="/features/wechat">微信功能开启</a></li></ul>',76)])])}const f=r(a,[["render",g]]);export{p as __pageData,f as default};
